import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    bias=0.0
    if cam:
        pts=[]
        for b,d in cam.get('walls',[]):
            a=math.radians(b)
            x=d*math.cos(a); y=d*math.sin(a)
            if -10<x<-3: pts.append((x,y))
        left=[y for x,y in pts if y>0]
        right=[y for x,y in pts if y<0]
        if left and right:
            bias=max(-8,min(8,(min(left)+max(right))*1.2))
    return (max(-25,min(25,2*h+bias)), -0.7, -41)

